from lib import *
S = SS('m38')
steps = [
    step("50 万个文档,k = 3i 有索引。{k: {$in: [S 个存在的值]}} 的耗时:S=1 0.2 ms;S=10 0.2 ms;S=100 0.3 ms;S=1,000 2.2 ms;S=10,000(去重后 9,903)17 ms;S=100,000(去重后 90,619)126 ms。每个值的平均代价从 237.5 μs(S=1,主要是固定开销)降到 1.4 μs;检查的键数约是返回数的 2 倍(S=1,000 返回 1,000、检查 1,996)。", t=tl(S(1)), mark=lidx(S(1), '100,000', '10,000'), done=lidx(S(1), '         1', '       100'), b=bars([['S=1', 0.2, '0.2 ms'], ['S=100', 0.3, '0.3 ms'], ['S=1,000', 2.2, '2.2 ms'], ['S=10,000', 17, '17 ms'], ['S=100,000', 126, '126 ms']], 126, mark=[3, 4], done=[0, 1, 2]), kv=KV([['固定开销', '约 0.2 ms'], ['每个值', '约 1.4~2 μs'], ['检查的键', '约返回数的 2 倍']], ['每个值'])),
    step("规划本身的耗时(explain queryPlanner 的 optimizationTimeMicros):S=1 130 μs;S=100 98 μs;S=10,000 478 μs;S=100,000 4,428 μs——$in 很大时光是选计划就要几毫秒。", t=tl(S(2)), mark=lidx(S(2), '10,000', '100,000'), done=lidx(S(2), 'S=      1', 'S=    100'), kv=KV([['S=100,000', '规划 4.4 ms'], ['S=100 以内', '规划不到 0.2 ms']], ['S=100,000'])),
    step("结果按索引键顺序返回,不是列表顺序:{k: {$in: [300, 3, 150, 3]}} 返回 [3, 150, 300];indexBounds 是排序、去重后的三个单点区间 [3, 3]、[150, 150]、[300, 300](重复的 3 只匹配一次)。", t=tl(S(3)), mark=lidx(S(3), '[ 3, 150, 300 ]'), done=lidx(S(3), '"[3, 3]"', '[150, 150]'), kv=KV([['返回顺序', '索引键顺序'], ['重复的值', '去重'], ['indexBounds', '排序后的单点区间']], ['返回顺序'])),
    step("没有索引的字段上做 $in:全表扫描 50 万个文档,S=10 要 79 ms,S=1,000 要 97 ms,S=100,000 要 200 ms——元素越多匹配越慢,但增长平缓(10,000 倍的元素只多了 2.5 倍耗时)。", t=tl(S(4)), mark=lidx(S(4), 'S=100,000'), done=lidx(S(4), 'S=     10', 'S=  1,000'), kv=KV([['无索引', '全表扫描 50 万个文档'], ['S 从 10 到 100,000', '79 → 200 ms']], ['无索引'])),
    step("同一条件写成 $in 或 1000 个 $or 分支(S=1,000):$in 1.9 ms,$or 2.2 ms,耗时接近。", t=tl(S(5)), mark=lidx(S(5), '$or 1000 个分支'), done=lidx(S(5), '$in 1.9 ms'), kv=KV([['$in', '1.9 ms'], ['$or 1000 个分支', '2.2 ms']], ['$in'])),
    step("上限:150 万个整数的 $in(BSON 数组 18,388,903 字节)在客户端就被拒绝,DocumentTooLarge:BSON document too large (18388999 bytes) - the connected server supports BSON document sizes up to 16777216 bytes;100 万个整数(11,888,903 字节)成功,返回 333,334 个,耗时 477 ms。", t=tl(S(6)), mark=lidx(S(6), 'DocumentTooLarge'), done=lidx(S(6), '100 万个整数'), kv=KV([['整条命令', '不能超过约 16 MB'], ['100 万个整数', '成功,477 ms'], ['150 万个整数', '客户端拒绝']], ['整条命令'])),
]
A = mkartm('m38', 38, 'MongoDB,$in,索引,查询,性能,真实验证,动画演示',
    '实测 $in 元素数量对查询的影响:S 从 1 到 100,000 耗时 0.2 ms 到 126 ms(每个值约 1.4 μs,检查的键约是返回数的 2 倍);规划耗时在 S=100,000 时达 4.4 ms;结果按索引键顺序返回、重复值去重;无索引时全表扫描 79 到 200 ms;$in 与 $or 接近;150 万个整数的 $in 超出 16 MB 上限。',
    '$in 里放多少个值合适?对索引查询的耗时、规划时间和结果顺序有什么影响?这篇把元素数量从 1 逐步增大到 100,000 测一遍,还试了无索引、与 $or 对比和大小上限。',
    [('126 ms', '$in 有 10 万个值(去重后 90,619 个)的索引查询耗时'), ('4.4 ms', '$in 有 10 万个值时仅规划就用掉的时间(optimizationTimeMicros 4,428 μs)'), ('18,388,903 字节', '150 万个整数的 $in 数组大小,超过 16 MB 在客户端被拒绝')],
    [('耗时随元素数增长', '<p>固定开销约 0.2 ms,之后每个值约 1.4~2 μs:1,000 个 2.2 ms,10 万个 126 ms。</p>'),
     ('规划开销', '<p>$in 小于一百个时规划不到 0.2 ms,10 万个时规划本身要 4.4 ms。</p>'),
     ('顺序与去重', '<p>结果按索引键顺序返回,不是 $in 列表的顺序;重复的值只匹配一次。</p>'),
     ('无索引', '<p>全表扫描时元素越多越慢但增长平缓:50 万个文档上 S=10 用 79 ms,S=100,000 用 200 ms。</p>'),
     ('$in 与 $or', '<p>同样的 1000 个值,$in 与 1000 个 $or 分支耗时接近(1.9 与 2.2 ms)。</p>'),
     ('上限', '<p>整条命令受 16 MB 上限约束:100 万个整数的 $in(11.9 MB)能执行,150 万个(18.4 MB)被拒绝。</p>')],
    steps,
    [ENV_M + '。50 万个文档;$in 的取值从已存在的 k 里采样;耗时是 pymongo 的 3~5 次中位数',
     '没有验证:$in 里放正则、null、数组元素的行为;$in 与排序、limit 的组合(合并排序);复合索引上 $in 的边界扩展;$in 很大时对计划缓存的影响;分片集群上的 $in 路由(下面分片篇)'],
    '$in 元素数量')
